tructions":["Adjust the chest pad and seat so the handles are reachable with long arms.","Pull without leaving the pad and return through a controlled reach.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep chest on the pad.","Use a repeatable range."],"mistakes":["Driving the torso backward or shrugging.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"iso-lateral-machine-row","name":"Iso-Lateral Machine Row","family":"row","pattern":"horizontal_pull","role":"primary","primaryMuscles":["back"],"secondaryMuscles":["biceps"],"requiredEquipment":["machines"],"skill":"beginner","fatigueCost":2,"setupMinutes":2,"repRange":[6,20],"progressionSuitability":5,"unilateral":true,"instructions":["Set the support so each lever can move through a full controlled path.","Row one or both arms while keeping the torso square, then reach forward slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Match side-to-side range.","Use a repeatable range."],"mistakes":["Rotating to gain distance or pulling one side faster.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_or_back_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"machine-pullover","name":"Machine Pullover","family":"shoulder_extension","pattern":"vertical_pull","role":"secondary","primaryMuscles":["back"],"secondaryMuscles":["triceps","chest"],"requiredEquipment":["machines"],"skill":"new","fatigueCost":2,"setupMinutes":2,"repRange":[8,20],"progressionSuitability":5,"unilateral":false,"instructions":["Adjust the seat and elbow pads so the machine pivot aligns near the shoulders.","Sweep the arms down through the machine arc and return without lifting the ribs.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Move from the shoulders.","Use a repeatable range."],"mistakes":["Pressing with the hands or arching the back.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_or_back_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"wide-grip-lat-pulldown","name":"Wide-Grip Lat Pulldown","family":"vertical_pull","pattern":"vertical_pull","role":"primary","primaryMuscles":["back"],"secondaryMuscles":["biceps"],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":2,"setupMinutes":2,"repRange":[6,15],"progressionSuitability":4,"unilateral":false,"instructions":["Take a comfortable wide overhand grip and secure the thighs.","Pull toward the upper chest with elbows moving down, then return smoothly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Stay tall under the bar.","Use a repeatable range."],"mistakes":["Pulling behind the neck or using a large backward lean.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"close-grip-lat-pulldown","name":"Close-Grip Lat Pulldown","family":"vertical_pull","pattern":"vertical_pull","role":"primary","primaryMuscles":["back"],"secondaryMuscles":["biceps"],"requiredEquipment":["cables"],"skill":"new","fatigueCost":2,"setupMinutes":2,"repRange":[6,20],"progressionSuitability":5,"unilateral":false,"instructions":["Attach a close neutral handle and secure the thighs beneath the pad.","Pull toward the upper chest and return until the arms are long.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Drive elbows toward pockets.","Use a repeatable range."],"mistakes":["Rocking backward or stopping the return early.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"machine-lat-pulldown","name":"Machine Lat Pulldown","family":"vertical_pull","pattern":"vertical_pull","role":"primary","primaryMuscles":["back"],"secondaryMuscles":["biceps"],"requiredEquipment":["machines"],"skill":"new","fatigueCost":2,"setupMinutes":2,"repRange":[6,20],"progressionSuitability":5,"unilateral":false,"instructions":["Adjust the seat and thigh restraint so the handles are reachable overhead.","Pull both levers down while staying supported and return under control.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep shoulders away from ears.","Use a repeatable range."],"mistakes":["Lifting from the seat or slamming the levers upward.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"plate-loaded-lat-pulldown","name":"Plate-Loaded Lat Pulldown","family":"vertical_pull","pattern":"vertical_pull","role":"primary","primaryMuscles":["back"],"secondaryMuscles":["biceps"],"requiredEquipment":["machines"],"skill":"beginner","fatigueCost":3,"setupMinutes":2,"repRange":[6,15],"progressionSuitability":5,"unilateral":false,"instructions":["Load both sides evenly and secure the thighs beneath the restraint.","Pull the levers down toward the sides and return to long arms.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Match both lever paths.","Use a repeatable range."],"mistakes":["Uneven loading or leaning back to turn it into a row.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-high-row","name":"Cable High Row","family":"row","pattern":"horizontal_pull","role":"secondary","primaryMuscles":["back"],"secondaryMuscles":["biceps","shoulders"],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":2,"setupMinutes":2,"repRange":[8,20],"progressionSuitability":4,"unilateral":false,"instructions":["Set the cable above shoulder height and take a supported seated or staggered position.","Pull down and back toward the upper ribs, then reach forward under control.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Elbows travel down and back.","Use a repeatable range."],"mistakes":["Using trunk momentum or pulling only with the hands.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_or_back_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-rear-delt-row","name":"Cable Rear-Delt Row","family":"rear_delt_row","pattern":"horizontal_pull","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":["back","biceps"],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":4,"unilateral":false,"instructions":["Set the cable near chest height and use a grip that permits open elbows.","Row toward the upper chest with elbows wide, then return slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Lead with wide elbows.","Use a repeatable range."],"mistakes":["Shrugging or pulling toward the waist.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"machine-shrug","name":"Machine Shrug","family":"shrug","pattern":"isolation","role":"accessory","primaryMuscles":["back"],"secondaryMuscles":["shoulders"],"requiredEquipment":["machines"],"skill":"new","fatigueCost":2,"setupMinutes":2,"repRange":[8,25],"progressionSuitability":5,"unilateral":false,"instructions":["Stand or sit centered with the handles held evenly at the sides.","Elevate the shoulders straight upward, pause, and lower fully.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Move shoulders toward ears.","Use a repeatable range."],"mistakes":["Rolling the shoulders or bending the elbows.","Adding load after position or control is lost."],"cautionTags":["reported_neck_or_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-shrug","name":"Cable Shrug","family":"shrug","pattern":"isolation","role":"accessory","primaryMuscles":["back"],"secondaryMuscles":["shoulders"],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":4,"unilateral":false,"instructions":["Hold a low cable attachment with arms long and torso tall.","Raise the shoulders vertically, pause, and lower without leaning.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep arms passive.","Use a repeatable range."],"mistakes":["Rowing the attachment or circling the shoulders.","Adding load after position or control is lost."],"cautionTags":["reported_neck_or_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"machine-lateral-raise","name":"Machine Lateral Raise","family":"lateral_raise","pattern":"isolation","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":[],"requiredEquipment":["machines"],"skill":"new","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":5,"unilateral":false,"instructions":["Adjust the seat so the pads contact the outer arms above the elbows.","Raise the arms outward through a comfortable arc and lower slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Lead with the elbows.","Use a repeatable range."],"mistakes":["Shrugging or lifting the torso from the seat.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-front-raise","name":"Cable Front Raise","family":"front_raise","pattern":"isolation","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":["core"],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":4,"unilateral":false,"instructions":["Stand over or just ahead of a low cable with the attachment at the thighs.","Raise the arms forward to a comfortable height and lower under tension.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep ribs stacked.","Use a repeatable range."],"mistakes":["Leaning backward or swinging the attachment.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"machine-front-raise","name":"Machine Front Raise","family":"front_raise","pattern":"isolation","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":[],"requiredEquipment":["machines"],"skill":"new","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":5,"unilateral":false,"instructions":["Adjust the seat and handles so the arms begin comfortably beside the torso.","Raise along the machine arc and return without the stack landing.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Stay against the pad.","Use a repeatable range."],"mistakes":["Shrugging or forcing the arms above a comfortable height.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-reverse-fly","name":"Cable Reverse Fly","family":"rear_delt_fly","pattern":"isolation","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":["back"],"requiredEquipment":["cables"],"skill":"intermediate","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":4,"unilateral":false,"instructions":["Set crossed cables near shoulder height and stand centered with soft elbows.","Open the arms wide without changing elbow angle, then return slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Reach outward, not backward.","Use a repeatable range."],"mistakes":["Using torso rotation or excessive cable load.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-y-raise","name":"Cable Y-Raise","family":"scapular_raise","pattern":"isolation","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":["back"],"requiredEquipment":["cables"],"skill":"intermediate","fatigueCost":1,"setupMinutes":2,"repRange":[10,20],"progressionSuitability":3,"unilateral":false,"instructions":["Set both cables low, cross the handles, and stand tall between the stacks.","Raise the arms diagonally into a Y and lower without losing trunk position.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Reach up and out.","Use a repeatable range."],"mistakes":["Arching the back or shrugging aggressively.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_or_back_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-upright-row","name":"Cable Upright Row","family":"upright_row","pattern":"vertical_pull","role":"accessory","primaryMuscles":["shoulders"],"secondaryMuscles":["back","biceps"],"requiredEquipment":["cables"],"skill":"intermediate","fatigueCost":1,"setupMinutes":2,"repRange":[8,20],"progressionSuitability":3,"unilateral":false,"instructions":["Hold a low cable attachment with a comfortable grip and stand tall.","Pull upward with elbows leading only to a comfortable height, then lower slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Stop below discomfort.","Use a repeatable range."],"mistakes":["Using a narrow painful grip or raising beyond shoulder comfort.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_or_wrist_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"machine-biceps-curl","name":"Machine Biceps Curl","family":"elbow_flexion","pattern":"isolation","role":"accessory","primaryMuscles":["biceps"],"secondaryMuscles":[],"requiredEquipment":["machines"],"skill":"new","fatigueCost":1,"setupMinutes":2,"repRange":[8,25],"progressionSuitability":5,"unilateral":false,"instructions":["Adjust the seat so the elbows align with the machine pivot and support.","Curl the handles without lifting the upper arms, then lower slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep elbows supported.","Use a repeatable range."],"mistakes":["Hyperextending at the bottom or lifting the torso.","Adding load after position or control is lost."],"cautionTags":["reported_elbow_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-biceps-curl","name":"Cable Biceps Curl","family":"elbow_flexion","pattern":"isolation","role":"accessory","primaryMuscles":["biceps"],"secondaryMuscles":[],"requiredEquipment":["cables"],"skill":"new","fatigueCost":1,"setupMinutes":2,"repRange":[8,25],"progressionSuitability":5,"unilateral":false,"instructions":["Hold a low cable attachment with arms long and torso upright.","Curl while the upper arms stay near the sides, then lower under tension.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep elbows quiet.","Use a repeatable range."],"mistakes":["Leaning backward or allowing wrists to fold.","Adding load after position or control is lost."],"cautionTags":["reported_elbow_or_wrist_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"bayesian-cable-curl","name":"Bayesian Cable Curl","family":"elbow_flexion","pattern":"isolation","role":"accessory","primaryMuscles":["biceps"],"secondaryMuscles":["shoulders"],"requiredEquipment":["cables"],"skill":"intermediate","fatigueCost":1,"setupMinutes":2,"repRange":[10,20],"progressionSuitability":4,"unilateral":true,"instructions":["Face away from a low cable with one arm extended slightly behind the torso.","Curl without moving the upper arm forward, then return to a comfortable stretch.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Upper arm stays behind.","Use a repeatable range."],"mistakes":["Rotating the torso or forcing shoulder extension.","Adding load after position or control is lost."],"cautionTags":["reported_elbow_or_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"rope-hammer-curl","name":"Rope Hammer Curl","family":"elbow_flexion","pattern":"isolation","role":"accessory","primaryMuscles":["biceps"],"secondaryMuscles":[],"requiredEquipment":["cables"],"skill":"new","fatigueCost":1,"setupMinutes":2,"repRange":[8,25],"progressionSuitability":5,"unilateral":false,"instructions":["Attach a rope low and hold both ends with neutral hands.","Curl the rope while keeping thumbs up, then lower until the arms are long.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Maintain neutral wrists.","Use a repeatable range."],"mistakes":["Flaring the rope with the shoulders or swinging.","Adding load after position or control is lost."],"cautionTags":["reported_elbow_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"reverse-grip-cable-curl","name":"Reverse-Grip Cable Curl","family":"elbow_flexion","pattern":"isolation","role":"accessory","primaryMuscles":["biceps"],"secondaryMuscles":[],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":1,"setupMinutes":2,"repRange":[10,20],"progressionSuitability":4,"unilateral":false,"instructions":["Hold a low straight-bar attachment with a comfortable overhand grip.","Curl while the wrists remain aligned, then lower under control.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Knuckles stay level.","Use a repeatable range."],"mistakes":["Bending the wrists or using hip momentum.","Adding load after position or control is lost."],"cautionTags":["reported_wrist_or_elbow_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"single-arm-cable-triceps-extension","name":"Single-Arm Cable Triceps Extension","family":"elbow_extension","pattern":"isolation","role":"accessory","primaryMuscles":["triceps"],"secondaryMuscles":[],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":4,"unilateral":true,"instructions":["Set a single handle above shoulder height and place the upper arm near the torso.","Extend the elbow without moving the shoulder, then return slowly.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep the elbow pinned.","Use a repeatable range."],"mistakes":["Rotating the torso or snapping into lockout.","Adding load after position or control is lost."],"cautionTags":["reported_elbow_or_shoulder_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"cable-triceps-kickback","name":"Cable Triceps Kickback","family":"elbow_extension","pattern":"isolation","role":"accessory","primaryMuscles":["triceps"],"secondaryMuscles":["core"],"requiredEquipment":["cables"],"skill":"beginner","fatigueCost":1,"setupMinutes":2,"repRange":[10,25],"progressionSuitability":4,"unilateral":true,"instructions":["Set a low cable, hinge slightly, and hold the upper arm beside the torso.","Extend the forearm behind the body and return without dropping the elbow.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Upper arm stays still.","Use a repeatable range."],"mistakes":["Swinging the shoulder or extending the low back.","Adding load after position or control is lost."],"cautionTags":["reported_elbow_or_back_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"},{"slug":"assisted-dip-machine","name":"Assisted Dip Machine","family":"dip","pattern":"vertical_push","role":"secondary","primaryMuscles":["triceps","chest"],"secondaryMuscles":["shoulders"],"requiredEquipment":["machines"],"skill":"new","fatigueCost":2,"setupMinutes":3,"repRange":[6,20],"progressionSuitability":5,"unilateral":false,"instructions":["Set enough assistance, mount securely, and take a stable grip before kneeling or standing on the pad.","Lower through a comfortable shoulder range and press until the arms are controlled.","Complete the final repetition with the same controlled path, then return the load safely."],"cues":["Keep shoulders down.","Use a repeatable range."],"mistakes":["Using too little assistance or bouncing from the bottom.","Adding load after position or control is lost."],"cautionTags":["reported_shoulder_or_elbow_discomfort"],"reviewStatus":"reviewed","contentVersion":"1.0.0","license":"STHENO_ORIGINAL"}]$el1$::jsonb))
insert into public.exercises(slug,name,status,family,movement_pattern,exercise_role,primary_muscles,secondary_muscles,required_equipment,skill_level,fatigue_cost,progression_suitability,rep_min,rep_max,education,caution_tags,content_version,license_key,review_status)
select e->>'slug',e->>'name','production',e->>'family',e->>'pattern',e->>'role',array(select jsonb_array_elements_text(e->'primaryMuscles')),array(select jsonb_array_elements_text(e->'secondaryMuscles')),array(select jsonb_array_elements_text(e->'requiredEquipment')),e->>'skill',(e->>'fatigueCost')::smallint,(e->>'progressionSuitability')::smallint,(e->'repRange'->>0)::smallint,(e->'repRange'->>1)::smallint,jsonb_build_object('setup',jsonb_build_array(e->'instructions'->>0),'execution',jsonb_build_array(e->'instructions'->>1,e->'instructions'->>2),'cues',e->'cues','mistakes',e->'mistakes'),array(select jsonb_array_elements_text(e->'cautionTags')),'1.0.0','STHENO_ORIGINAL','reviewed' from batch
